#!/usr/bin/env node
/**
 * `npm run review:tally`
 *
 * Unblind the labelling: join the labels to the key and report what the rule actually fires on.
 *
 * ## The two numbers that matter, for both rules
 *
 * 1. **Enrichment** — how much more often the code the rule is *named after* appears in the trigger
 *    group than in the matched negatives. A rule whose name-code is no more common in its own triggers
 *    has no discriminating power, whatever its precision looks like.
 * 2. **Missed cases** — how often that same code appears in the negatives. With matched negatives of
 *    the same length, turn count and domain, a negative that carries the behaviour is a miss, and a
 *    rule that is precise and misses a lot is a different finding from a rule that finds nothing.
 *
 * Nothing here is folded into a single score, and no threshold is applied: the counts are the result.
 * Text is never printed — not the reply, not the note.
 */

import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..', '..');
const DIR = path.join(ROOT, '.external-corpora', 'review');
const OUT = path.join(HERE, 'REVIEW_RESULTS.md');

interface KeyEntry {
  readonly id: string;
  readonly group: 'trigger' | 'matched-negative';
  readonly rule: string;
  readonly chars: number;
  readonly turns: number;
  readonly domain: string;
}

interface Label {
  readonly id: string;
  readonly label: string;
  readonly confidence: string;
  readonly note?: string;
  /** Offer round only: would the reply read as an assistant's, setting the offer aside? */
  readonly shaped?: string;
  /** Offer round only: could the code have been decided without the user turn? */
  readonly needsContext?: string;
}

const RULES: ReadonlyArray<{ rule: string; keyPrefix: string; prefix: string; codes: readonly string[]; nameCode: string; nameCodeMeaning: string }> = [
  {
    rule: 'chat.auto_summary',
    keyPrefix: 'auto_summary',
    prefix: 'auto',
    codes: ['A', 'B', 'C', 'D', 'E'],
    nameCode: 'A',
    nameCodeMeaning: 'unnecessary recap',
  },
  {
    rule: 'chat.mirrors_user',
    keyPrefix: 'mirrors_user',
    prefix: 'mirror',
    codes: ['A', 'B', 'C', 'D', 'E', 'F'],
    nameCode: 'A',
    nameCodeMeaning: 'genuine mirroring',
  },
  {
    rule: 'chat.unsolicited_offer',
    keyPrefix: 'unsolicited_offer',
    prefix: 'offer',
    codes: ['A', 'B', 'C', 'D', 'E', 'F'],
    nameCode: 'A',
    nameCodeMeaning: 'genuine unsolicited offer',
  },
];

function readLabels(prefix: string): Label[] {
  const files = existsSync(path.join(DIR, 'labels'))
    ? readdirSync(path.join(DIR, 'labels')).filter((name) => name.startsWith(`${prefix}-`) && name.endsWith('.jsonl'))
    : [];
  const out: Label[] = [];
  for (const file of files) {
    for (const line of readFileSync(path.join(DIR, 'labels', file), 'utf8').split('\n')) {
      if (line.trim().length === 0) continue;
      try {
        out.push(JSON.parse(line) as Label);
      } catch {
        // A malformed line is counted by its absence: the totals below are per sample id.
      }
    }
  }
  return out;
}

function main(): number {
  const lines: string[] = [];
  const push = (...text: string[]): void => {
    for (const line of text) lines.push(line);
  };
  const pct = (value: number, total: number): string => `${((value / Math.max(1, total)) * 100).toFixed(1)}%`;
  const bucket = (chars: number): string => (chars < 200 ? 'xs<200' : chars < 600 ? 'short<600' : chars < 1500 ? 'medium<1500' : 'long>=1500');

  push(
    '# Blind review: what the rules actually fire on',
    '',
    '<!-- Generated by `npm run review:tally`. Counts only: no source text. -->',
    '',
    'Triggers and matched negatives were shuffled into one blind sheet, labelled without knowing the',
    'group, and joined back to the key only now. The rubric and the sheet hashes are recorded beside each',
    'sheet — `review-rubric.md` for the first round, `offer-rubric.md` for the offer round — and the labels',
    'were written before the key was opened.',
    '',
    'The offer round also asks two questions the earlier rounds did not: whether the reply reads as an',
    'assistant\'s **setting the offer aside**, and whether the code could have been decided **without the',
    'user turn**. A rule can enrich for the behaviour it is named after and still not be measuring assistant',
    'behaviour, and this is where that shows.',
    '',
  );

  for (const { rule, keyPrefix, prefix, codes, nameCode, nameCodeMeaning } of RULES) {
    const keyFile = path.join(DIR, `${keyPrefix}-key.json`);
    if (!existsSync(keyFile)) {
      push(`## ${rule}`, '', 'No key file: the sheet was never generated in this checkout.', '');
      continue;
    }
    const key = JSON.parse(readFileSync(keyFile, 'utf8')) as KeyEntry[];
    const labels = readLabels(prefix);
    const labelById = new Map(labels.map((label) => [label.id, label]));
    const keyById = new Map(key.map((entry) => [entry.id, entry]));
    const missing = key.filter((entry) => !labelById.has(entry.id)).length;
    const stray = labels.filter((label) => !keyById.has(label.id)).length;

    const count = (group: 'trigger' | 'matched-negative', code: string, only?: string): number =>
      key.filter(
        (entry) =>
          entry.group === group &&
          labelById.get(entry.id)?.label === code &&
          (only === undefined || labelById.get(entry.id)?.confidence === only),
      ).length;
    const n = (group: 'trigger' | 'matched-negative', only?: string): number =>
      key.filter(
        (entry) => entry.group === group && (only === undefined || labelById.get(entry.id)?.confidence === only),
      ).length;

    const triggers = n('trigger');
    const negatives = n('matched-negative');

    push(
      `## ${rule}`,
      '',
      `Paired samples: ${triggers} triggers, ${negatives} matched negatives (matched on response-length bucket, turn count and domain). ` +
        `Labels missing: ${missing}. Labels without a sample: ${stray}.`,
      '',
      `### Distribution of codes`,
      '',
      `| Code | Triggers | Matched negatives |`,
      `| --- | --- | --- |`,
      ...codes.map((code) => `| \`${code}\` | ${count('trigger', code)} (${pct(count('trigger', code), triggers)}) | ${count('matched-negative', code)} (${pct(count('matched-negative', code), negatives)}) |`),
      '',
      `### The code the rule is named after: \`${nameCode}\` — ${nameCodeMeaning}`,
      '',
      `| Measure | Value |`,
      `| --- | --- |`,
      `| In the trigger group | ${count('trigger', nameCode)}/${triggers} (${pct(count('trigger', nameCode), triggers)}) |`,
      `| In the matched negatives | ${count('matched-negative', nameCode)}/${negatives} (${pct(count('matched-negative', nameCode), negatives)}) |`,
      `| Enrichment (trigger rate ÷ negative rate) | ${
        count('matched-negative', nameCode) === 0
          ? 'undefined, no negative carries it'
          : (count('trigger', nameCode) / Math.max(1, triggers) / (count('matched-negative', nameCode) / negatives)).toFixed(2) + '×'
      } |`,
      `| Precision, if the rule is treated as a \`${nameCode}\` detector | ${count('trigger', nameCode)}/${triggers} (${pct(count('trigger', nameCode), triggers)}) |`,
      `| Missed cases — negatives that are \`${nameCode}\` | ${count('matched-negative', nameCode)} |`,
      '',
      '### The same, on high confidence labels only',
      '',
      `| Measure | Value |`,
      `| --- | --- |`,
      `| \`${nameCode}\` in triggers | ${count('trigger', nameCode, 'high')}/${n('trigger', 'high')} (${pct(count('trigger', nameCode, 'high'), n('trigger', 'high'))}) |`,
      `| \`${nameCode}\` in negatives | ${count('matched-negative', nameCode, 'high')}/${n('matched-negative', 'high')} (${pct(count('matched-negative', nameCode, 'high'), n('matched-negative', 'high'))}) |`,
      '',
      '### Stability across the matching dimensions',
      '',
      `| Slice | \`${nameCode}\` in triggers | \`${nameCode}\` in negatives |`,
      `| --- | --- | --- |`,
      ...['xs<200', 'short<600', 'medium<1500', 'long>=1500'].map((b) => {
        const inBucket = (group: 'trigger' | 'matched-negative'): string => {
          const entries = key.filter((entry) => entry.group === group && bucket(entry.chars) === b);
          const hits = entries.filter((entry) => labelById.get(entry.id)?.label === nameCode).length;
          return `${hits}/${entries.length} (${pct(hits, entries.length)})`;
        };
        return `| \`${b}\` | ${inBucket('trigger')} | ${inBucket('matched-negative')} |`;
      }),
      ...['single', 'multi'].map((turns) => {
        const inTurns = (group: 'trigger' | 'matched-negative'): string => {
          const entries = key.filter(
            (entry) => entry.group === group && (turns === 'single' ? entry.turns <= 1 : entry.turns > 1),
          );
          const hits = entries.filter((entry) => labelById.get(entry.id)?.label === nameCode).length;
          return `${hits}/${entries.length} (${pct(hits, entries.length)})`;
        };
        return `| \`${turns}\` | ${inTurns('trigger')} | ${inTurns('matched-negative')} |`;
      }),
      '',
    );

    // The two construct questions, when the round asked them. Restricted to the samples labelled
    // with the name-code, because "is this rule measuring assistant behaviour" is a question about
    // what it fires on and gets right, not about every reply in the group.
    const hasConstruct = [...labelById.values()].some(
      (label) => label.shaped !== undefined || label.needsContext !== undefined,
    );
    if (hasConstruct) {
      const named = (group: 'trigger' | 'matched-negative'): Label[] =>
        key
          .filter((entry) => entry.group === group)
          .map((entry) => labelById.get(entry.id))
          .filter((label): label is Label => label !== undefined)
          .filter((label) => label.label === nameCode);
      const share = (group: 'trigger' | 'matched-negative', field: 'shaped' | 'needsContext', value: string): string => {
        const labels = named(group);
        const hits = labels.filter((label) => label[field] === value).length;
        return `${hits}/${labels.length} (${pct(hits, labels.length)})`;
      };
      push(
        `### Construct questions, on the \`${nameCode}\` labels only`,
        '',
        `Every sample labelled \`${nameCode}\` in either group — ${named('trigger').length} in the trigger group and`,
        `${named('matched-negative').length} in the negatives. Restricted to those, because the question is what the rule`,
        'gets right, not what everything in the group looks like.',
        '',
        `| Question | Value | \`${nameCode}\` triggers | \`${nameCode}\` in matched negatives |`,
        '| --- | --- | --- | --- |',
      );
      for (const value of ['yes', 'no', 'uncertain']) {
        push(`| assistant-shaped? | \`${value}\` | ${share('trigger', 'shaped', value)} | ${share('matched-negative', 'shaped', value)} |`);
      }
      for (const value of ['yes', 'no']) {
        push(`| requires user context? | \`${value}\` | ${share('trigger', 'needsContext', value)} | ${share('matched-negative', 'needsContext', value)} |`);
      }
      push(
        '',
        '**assistant-shaped?** was asked with the offer set aside: a rule whose positives are not',
        'assistant-shaped is measuring something else, however well it finds offers. **requires user',
        'context?** counts the triggers a response-only scan could not have decided, which is the size of',
        'the reach the rule does not have on its own.',
        '',
      );
    }
  }

  push(
    '## How to read this',
    '',
    '- **Enrichment near 1** means the rule fires on the behaviour it is named after no more often than on',
    '  the same-length replies where it did not fire. That is not a precision problem; it is an absence of',
    '  discriminating power.',
    '- **Enrichment well above 1 with many missed cases** is a high-precision, low-recall rule, which is a',
    '  different finding and a different remedy.',
    '- **Enrichment well above 1 with few missed cases** is a rule doing what its name says.',
    '- The high-confidence block is the answer to "does the disagreement between labellers explain this",',
    '  and the slice table is the answer to "is this a length or turn-count effect in disguise".',
    '- An `A` count in the negatives is a **missed case**, not a false positive: the rule did not fire and',
    '  the behaviour is present. Precision over the triggers and recall over the negatives are separate',
    '  numbers and neither is a score for the rule.',
    '',
    `Generated ${new Date().toISOString()}.`,
    '',
  );

  writeFileSync(OUT, `${lines.join('\n')}\n`, 'utf8');
  process.stdout.write('\nReview tally\n\n');
  for (const { rule, keyPrefix, prefix, nameCode } of RULES) {
    const keyFile = path.join(DIR, `${keyPrefix}-key.json`);
    if (!existsSync(keyFile)) continue;
    const key = JSON.parse(readFileSync(keyFile, 'utf8')) as KeyEntry[];
    const labelById = new Map(readLabels(prefix).map((label) => [label.id, label]));
    const hits = (group: 'trigger' | 'matched-negative'): string => {
      const entries = key.filter((entry) => entry.group === group);
      const fired = entries.filter((entry) => labelById.get(entry.id)?.label === nameCode).length;
      return `${fired}/${entries.length} (${pct(fired, entries.length)})`;
    };
    process.stdout.write(`  ${rule} ${nameCode}: triggers ${hits('trigger')}, negatives ${hits('matched-negative')}\n`);
  }
  process.stdout.write(`\nWritten to ${path.relative(ROOT, OUT).split('\\').join('/')}\n`);
  return 0;
}

process.exit(main());
